CREATE TABLE r AS SELECT a,b,sum(c)OVER(ORDER BY a GROUPS BETWEEN 1 PRECEDING AND 2 PRECEDING EXCLUDE CURRENT ROW) AS x1,sum(c)OVER(ORDER BY a GROUPS BETWEEN 1 PRECEDING AND 2 PRECEDING) AS x2,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 1 PRECEDING AND 2 PRECEDING EXCLUDE CURRENT ROW) AS x3,sum(c)OVER(ORDER BY a,b GROUPS BETWEEN 1 PRECEDING AND 2 PRECEDING) AS x4 FROM t3;